// ---------------------------------------------------------------------------
// English copy for the i18n shards (the corpus is English; design §7.1)
// ---------------------------------------------------------------------------

const EN = serverShards['en-US'] as Record<string, Record<string, unknown>>;

/** `interface/pages` → `privacyPolicy.title` etc. */
function shard(name: string): Record<string, unknown> {
  return (EN[name] ?? {}) as Record<string, unknown>;
}

function at(obj: unknown, path: string): unknown {
  return path.split('.').reduce<unknown>((o, k) => (o && typeof o === 'object' ? (o as Record<string, unknown>)[k] : undefined), obj);
}

function str(obj: unknown, path: string): string {
  const v = at(obj, path);
  return typeof v === 'string' ? fill(v) : '';
}

/** Fill the brand placeholders, strip inline markup, collapse whitespace. */
function fill(s: string): string {
  return s
    .replace(/\{\{brand\}\}/g, PHOTO_BRAND)
    .replace(/<\/?(strong|em|code|b|i|br|span)[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Every string leaf of a copy object, in key order, as paragraphs (keys skipped by `skip`). */
function flatten(obj: unknown, skip: RegExp = /^$/): string[] {
  const out: string[] = [];
  const walk = (v: unknown, key: string) => {
    if (skip.test(key)) return;
    if (typeof v === 'string') {
      if (/\{\{(?!brand)/.test(v)) return; // UI templates with runtime values
      const t = fill(v);
      if (t.length >= 3) out.push(t);
    } else if (Array.isArray(v)) v.forEach((x) => walk(x, key));
    else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) walk(x, k);
  };
  walk(obj, '');
  return out;
}

// ---------------------------------------------------------------------------
// Tier numbers (decision 3)
// ---------------------------------------------------------------------------

/** A price ($8, €80) or a daily count ("5 a day", "30/day", "per day"). */
const MONEY_OR_DAILY = /[$€£]\s?\d|\b\d[\d,.]*\s*(?:\/\s?day|per day|a day|each day|daily)\b/i;
/** A limit-shaped quantity: a size, a length, a count of jobs/projects/exports, an output height or megapixels. */
const LIMIT_QTY =
  /\b\d[\d,.]*\s*(?:[KMGT]B\b|minutes?\b|min\b|seconds?\b|s long\b|projects?\b|exports?\b|jobs?\b|operations?\b|ops\b|turns?\b|edits?\b|photos?\b|presets?\b|MP\b|megapixels?\b)|\b\d{3,4}p\b/i;
/** A plan named in the same sentence as a limit-shaped quantity ("a free account raises that to 1 GB"). */
const PLAN_NAME = /\b(?:guests?|free accounts?|free plan|free tier|premium|pro|without an account|no account|signed[- ]in users?|visitors? without|free tier covers)\b/i;

/** True when a sentence states a plan limit or a price. */
export function statesTierNumber(sentence: string): boolean {
  return MONEY_OR_DAILY.test(sentence) || (PLAN_NAME.test(sentence) && LIMIT_QTY.test(sentence));
}

/**
 * Drop every sentence that states a plan limit or a price, and replace it once
 * per text with a pointer to the live numbers. Numbers that are not limits
 * (formats, codecs, resolutions of a file, "24 hours") survive.
 */
export function stripTierNumbers(text: string): string {
  // Keep the line's indentation and list/FAQ marker ("  - ", "3. ", "A: ").
  const lead = /^\s*(?:(?:[-*]|\d+\.|[QA]:)\s+)?/.exec(text)?.[0] ?? '';
  let pointed = false;
  const parts = text.slice(lead.length).trim().split(/(?<=[.!?])\s+/);
  const kept: string[] = [];
  for (const p of parts) {
    if (statesTierNumber(p)) {
      if (!pointed) kept.push('Daily limits and file caps depend on the plan; quote them only from the live plan block.');
      pointed = true;
      continue;
    }
    kept.push(p);
  }
  const out = kept.join(' ').trim();
  return out ? lead + out : '';
}

function clean(lines: string[]): string[] {
  return lines.map(stripTierNumbers).filter((l) => l.length > 0);
}

// ---------------------------------------------------------------------------
// The doc shape
// ---------------------------------------------------------------------------

interface DocInput {
  title: string;
  route?: string;
  kind: DocKind;
  category: string;
  slug?: string;
  summary: string;
  details: string[];
  keywords: string[];
  links: string[];
  opens?: string[];
}

const uniq = (xs: string[]) => [...new Set(xs.map((x) => x.trim()).filter(Boolean))];

function doc(d: DocInput): string {
  const lines = [GENERATED_LINE, '', `# ${d.title}`, ''];
  if (d.route) lines.push(`- Route: \`${d.route}\``);
  lines.push(`- Kind: \`${d.kind}\``, `- Category: \`${d.category}\``);
  if (d.slug) lines.push(`- Slug: \`${d.slug}\``);
  lines.push('', '## Summary', '', stripTierNumbers(d.summary), '', '## Details', '', ...clean(d.details), '');
  lines.push('## Search keywords', '', uniq(d.keywords).map((k) => `\`${k.replace(/`/g, '')}\``).join(', '), '');
  lines.push('## Links', '', ...(d.links.length ? uniq(d.links).map((l) => `- ${l}`) : ['- (none)']), '');
  if (d.opens && d.opens.length) lines.push('## Opens', '', ...d.opens.map((o) => `- ${o}`), '');
  return lines.join('\n').replace(/\n{3,}/g, '\n\n').trimEnd() + '\n';
}

const bullets = (xs: readonly string[] | undefined) => (xs ?? []).map((x) => `- ${x}`);

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

const CATEGORY_LABEL = Object.fromEntries(TOOL_CATEGORIES.map((c) => [c.id, c.label])) as Record<string, string>;
CATEGORY_LABEL.contentStudio = 'Darkroom video editor';

/** The routes a tool page's embed can be opened with, as `preset` ids. */
export function toolPresets(tool: ToolPageContent): string[] {
  const wiring = PHOTO_PAGE_WIRING[tool.slug];
  if (tool.category === 'photo' || wiring) return BUILTIN_PRESETS.map((p) => p.id);
  return [];
}

/** What the tool page's panel opens set up for (the `embed` facts). */
function opensFacts(tool: ToolPageContent): string[] {
  const e = tool.embed;
  const out: string[] = [];
  const wiring = PHOTO_PAGE_WIRING[tool.slug];
  if (wiring) {
    out.push(`Opens the ${PHOTO_BRAND} editor with the ${wiring.panel} panel in front${wiring.preset ? ` and the ${wiring.preset} look applied` : ''}.`);
    out.push(`Built-in looks that can be named as a preset: ${BUILTIN_PRESETS.map((p) => p.id).join(', ')}.`);
    return out;
  }
  if (tool.slug === 'content-studio') return ['Opens the Darkroom editor (multi-track timeline) at /tools/content-studio.'];
  if (tool.slug === 'motion') return [`Opens the ${MOTION_BRAND} launcher; new projects start at /motion/new.`];
  out.push(`Panel: ${e.title}. Media kind: ${e.defaultMediaKind}; task: ${e.defaultTask}.`);
  const fmt = e.lockedOutputFormat ?? e.lockedVideoOutputFormat ?? e.lockedExtractAudioFormat;
  if (fmt) out.push(`Output format is fixed to ${fmt}.`);
  else if (e.defaultOutputFormat || e.defaultVideoOutputFormat || e.defaultExtractAudioFormat)
    out.push(`Default output format: ${e.defaultOutputFormat ?? e.defaultVideoOutputFormat ?? e.defaultExtractAudioFormat}.`);
  if (e.lockedInputFormat) out.push(`Input format is fixed to ${e.lockedInputFormat}.`);
  if (e.allowedInputFormats?.length) out.push(`Accepted inputs: ${e.allowedInputFormats.join(', ')}.`);
  if (e.defaultAIImageOperation) out.push(`AI image operation preselected: ${e.defaultAIImageOperation}.`);
  if (e.defaultVideoCompressionPreset) out.push(`Compression level preselected: ${e.defaultVideoCompressionPreset}.`);
  if (e.transcribeMode) out.push('Opens in transcription mode.');
  if (e.transcodeMode) out.push(`Opens in transcode mode${e.transcodeProtocol ? ` (${e.transcodeProtocol})` : ''}.`);
  if (e.preset) {
    const p = e.preset;
    const what =
      'aiOperation' in p ? `AI operation ${p.aiOperation}` :
      'panel' in p ? `panel ${p.panel}` :
      'effect' in p ? `effect ${p.effect}` : `metadata ${p.mode}`;
    out.push(`The form opens already set up for this task (${what}).`);
  }
  return out;
}

function toolDoc(tool: ToolPageContent): string {
  const aliases = aliasesOf(tool.slug);
  const f = tool.supportedFormats;
  const details: string[] = [tool.intro, '', '### What it does', '', ...bullets(tool.whatItDoes), ''];
  details.push('### How to use it', '', ...tool.flowSteps.map((s, i) => `${i + 1}. ${s.title}${s.description ? `: ${s.description}` : ''}`), '');
  if (f) {
    details.push('### Supported formats', '');
    if (f.supportedInputFormats?.length) details.push(`- Input: ${f.supportedInputFormats.join(', ')}`);
    if (f.supportedOutputFormats?.length) details.push(`- Output: ${f.supportedOutputFormats.join(', ')}`);
    details.push(...bullets(f.processingNotes), '');
  }
  if (tool.advancedDetails?.length) details.push('### Technical details', '', ...bullets(tool.advancedDetails), '');
  if (tool.whenNotToUse) details.push('### When not to use it', '', tool.whenNotToUse, '');
  details.push('### Use cases', '', ...tool.useCases.map((u) => `- ${u.title}: ${u.description}`), '');
  if (tool.faq.length) details.push('### FAQ', '', ...tool.faq.flatMap((q) => [`Q: ${q.question}`, `A: ${q.answer}`, '']));
  const keywords = [tool.slug, tool.name, tool.primaryKeyword, ...tool.secondaryKeywords, ...aliases, ...aliases.map((a) => a.replace(/-/g, ' '))];
  return doc({
    title: tool.name,
    route: `/tools/${tool.slug}`,
    kind: 'tool',
    category: tool.category,
    slug: tool.slug,
    summary: `${tool.tagline} ${CATEGORY_LABEL[tool.category] ? `(${CATEGORY_LABEL[tool.category]})` : ''}`.trim(),
    details,
    keywords,
    links: tool.related.filter((r) => r.to.startsWith('/')).map((r) => `[${r.label}](${r.to})`),
    opens: opensFacts(tool),
  });
}

