/** Section titles of a legal document (title + first paragraph each, no full text). */
function legalOutline(key: 'privacyPolicy' | 'termsOfService'): string[] {
  const sections = (at(pages(), `${key}.sections`) ?? []) as Array<{ title?: string; paragraphs?: string[]; subsections?: Array<{ title?: string }> }>;
  return sections.flatMap((s) => [
    `- ${fill(s.title ?? '')}: ${fill((s.paragraphs ?? [])[0] ?? '')}`.trim(),
    ...(s.subsections ?? []).map((sub) => `  - ${fill(sub.title ?? '')}`),
  ]);
}

