/** Layer type → the editor panel it lives in (mirrors components/photo/layers-panel.tsx panelForLayer; the test pins it). */
export const PHOTO_LAYER_PANEL: Record<LayerType, PhotoPanelId> = {
  exposure: 'basic', brightnessContrast: 'basic', tone: 'basic', whiteBalance: 'basic', vibranceSaturation: 'basic',
  curves: 'curves', levels: 'levels', hsl: 'hsl', colorBalance: 'colorBalance', blackWhite: 'blackWhite',
  channelMixer: 'channelMixer', photoFilter: 'photoFilter', splitTone: 'splitTone', lut: 'lut', redEye: 'redEye',
  sharpen: 'detail', blur: 'detail', noiseReduction: 'detail', clarity: 'detail', texture: 'detail', dehaze: 'detail',
  vignette: 'detail', grain: 'detail', invert: 'effects', posterize: 'effects', threshold: 'effects', gamma: 'effects',
};

/** Which i18n block labels a photo layer type's params. */
function photoParamLabels(photo: Record<string, unknown>, type: LayerType): Record<string, string> {
  const tryObj = (p: string) => (at(photo, p) && typeof at(photo, p) === 'object' ? (at(photo, p) as Record<string, unknown>) : null);
  const detailKey: Partial<Record<LayerType, string>> = { sharpen: 'detail.sharpen', blur: 'detail.blur', noiseReduction: 'detail.noise', vignette: 'detail.vignette', grain: 'detail.grain' };
  const src = tryObj(`params.${type}`) ?? (detailKey[type] ? tryObj(detailKey[type]!) : null) ?? tryObj(type) ?? {};
  const out: Record<string, string> = {};
  for (const [k, val] of Object.entries(src)) if (typeof val === 'string') out[k] = fill(val);
  return out;
}

