// ---------------------------------------------------------------------------
// routes.json, names/<locale>.json, index.json
// ---------------------------------------------------------------------------

export interface RouteEntry {
  route: string;
  kind: 'page' | 'tool' | 'editor';
  slug?: string;
  presets?: string[];
}

/** The closed list of navigable targets (navigate / open_tool validate against it). */
export function buildRoutes(specs: PageSpec[] = pageSpecs()): RouteEntry[] {
  const out: RouteEntry[] = specs.map((s) => ({ route: s.route, kind: 'page' as const }));
  for (const tab of ['history', 'projects', 'voices', 'billing', 'privacy', 'profile']) out.push({ route: `/account?tab=${tab}`, kind: 'page' });
  for (const t of PRIMARY_TOOL_PAGES) {
    const presets = toolPresets(t);
    out.push({ route: `/tools/${t.slug}`, kind: 'tool', slug: t.slug, ...(presets.length ? { presets } : {}) });
  }
  out.push({ route: '/motion/new', kind: 'editor', slug: 'motion' }, { route: '/photo/new', kind: 'editor', slug: 'aperture' });
  return out.sort((a, b) => a.route.localeCompare(b.route));
}

/** Localized names + locale-prefixed paths for every tool and page (decision 8). */
export function buildNames(locale: string, specs: PageSpec[] = pageSpecs()): Record<string, { name: string; path: string }> {
  const out: Record<string, { name: string; path: string }> = {};
  for (const t of PRIMARY_TOOL_PAGES) {
    const loc = getLocalizedToolBySlug(t.slug, locale) ?? t;
    out[`tools/${t.slug}`] = { name: loc.name, path: localizeHref(`/tools/${t.slug}`, locale) };
  }
  const sh = serverShards[locale] ?? {};
  const nav = (sh['interface/_core'] ?? {}) as Record<string, unknown>;
  const pg = (sh['interface/pages'] ?? {}) as Record<string, unknown>;
  const ar = (sh['interface/articles'] ?? {}) as Record<string, unknown>;
  // The locale's own nav label first, then the page's own title key; English last.
  const NAME_KEYS: Record<string, Array<[Record<string, unknown>, string]>> = {
    '/': [[nav, 'topNav.home']], '/tools': [[nav, 'topNav.tools']], '/about': [[nav, 'topNav.about']],
    '/how-it-works': [[nav, 'topNav.howItWorks']], '/tutorials': [[nav, 'topNav.tutorials']],
    '/privacy-policy': [[nav, 'topNav.privacyPolicy']], '/terms-of-service': [[nav, 'topNav.termsOfService']],
    '/blog': [[nav, 'topNav.blog']], '/voices': [[nav, 'topNav.voices']], '/contact': [[nav, 'topNav.contact']],
    '/pricing': [[nav, 'topNav.pricing']], '/changelog': [[nav, 'footer.changelog']], '/status': [[nav, 'footer.status']],
    '/licenses': [[nav, 'footer.licenses']], '/delete-account': [[nav, 'footer.deleteAccount']], '/account': [[pg, 'account.title']],
    '/blog/video/video-compression-guide': [[ar, 'blogVideoCompression.title']],
    '/blog/image/image-optimization-guide': [[ar, 'blogImageOptimization.title']],
    '/blog/audio/audio-quality-guide': [[ar, 'blogAudioQuality.title']],
    '/tutorials/video/getting-started': [[ar, 'tutorialVideoGettingStarted.title']],
    '/tutorials/image/getting-started': [[ar, 'tutorialImageGettingStarted.title']],
    '/tutorials/audio/getting-started': [[ar, 'tutorialAudioGettingStarted.title']],
    '/tutorials/ai-frame-interpolation': [[ar, 'tutorialAiFrameInterpolation.title']],
    '/tutorials/content-studio': [[pg, 'tutorials.tutorials.contentStudio.title']],
    '/tutorials/motion': [[pg, 'tutorials.tutorials.motion.title']],
    '/tutorials/aperture': [[pg, 'tutorials.tutorials.aperture.title']],
  };
  for (const s of specs) {
    const found = (NAME_KEYS[s.route] ?? []).map(([o, k]) => at(o, k)).find((v): v is string => typeof v === 'string' && v.trim() !== '');
    out[pageFile(s.route).replace(/\.md$/, '')] = { name: found ? fill(found) : s.title, path: localizeHref(s.route, locale) };
  }
  return Object.fromEntries(Object.entries(out).sort(([a], [b]) => a.localeCompare(b)));
}

/** Conservative token estimate (chars / 3.5), the same rule the API uses. */
export const estimateTokens = (s: string): number => Math.ceil(s.length / 3.5);

function indexEntry(path: string, body: string) {
  const title = /^# (.+)$/m.exec(body)?.[1] ?? path;
  const kind = /- Kind: `([^`]+)`/.exec(body)?.[1] ?? '';
  const kw = /## Search keywords\n\n(.+)\n/.exec(body)?.[1] ?? '';
  return {
    title,
    kind,
    keywords: kw.split(', ').map((k) => k.replace(/`/g, '')).filter(Boolean),
    tokens: estimateTokens(body),
  };
}

const stableJson = (v: unknown) => JSON.stringify(v, null, 1) + '\n';

// ---------------------------------------------------------------------------
// The whole corpus
// ---------------------------------------------------------------------------

// ---------------------------------------------------------------------------
// Recipes (MM106, design §7.2): hand-written, exported in the same doc shape
// ---------------------------------------------------------------------------

/** Read and parse every recipe under `root` (default: the UI repo's content/medi/recipes). */
export function loadRecipes(root: string = join(process.cwd(), MEDI_RECIPES_DIR)): Recipe[] {
  const walk = (dir: string): string[] =>
    readdirSync(dir).flatMap((n) => {
      const p = join(dir, n);
      return statSync(p).isDirectory() ? walk(p) : n.endsWith('.md') ? [p] : [];
    });
  return walk(root)
    .map((p) => parseRecipe(relative(root, p).split('\\').join('/'), readFileSync(p, 'utf8')))
    .sort((a, b) => a.path.localeCompare(b.path));
}

const RECIPE_EDITOR_LABEL: Record<string, string> = { photo: PHOTO_BRAND, studio: 'Darkroom', vector: MOTION_BRAND, workflow: 'Cross-tool workflow' };

/** First sentence of a section, for the doc summary and the capsule line. */
const firstSentenceOf = (s: string) => (/^([\s\S]+?[.!?])(\s|$)/.exec(s.replace(/\s+/g, ' ').trim())?.[1] ?? s).trim();

export function recipeDoc(r: Recipe): string {
  const details: string[] = [];
  for (const name of RECIPE_SECTIONS) details.push(`### ${name}`, '', ...r.sections[name].split('\n'), '');
  return doc({
    title: r.title,
    kind: 'recipe',
    category: r.editor,
    slug: `${r.editor}/${r.id}`,
    summary: `${RECIPE_EDITOR_LABEL[r.editor]} recipe (${r.difficulty}). ${firstSentenceOf(r.sections['What a pro does and why'])}`,
    details,
    keywords: [r.title, ...r.intents],
    links: r.tools.map((slug) => `/tools/${slug}`),
  });
}

/** Every Medi knowledge file keyed by its path relative to `knowledge/`. */
export function buildMediKnowledge(recipes: Recipe[] = loadRecipes()): Record<string, string> {
  const files: Record<string, string> = {};
  for (const t of PRIMARY_TOOL_PAGES) files[`tools/${t.slug}.md`] = toolDoc(t);
  const specs = pageSpecs();
  for (const s of specs) files[pageFile(s.route)] = pageDoc(s);
  for (const [p, body] of [...studioDocs(), ...vectorDocs(), ...photoDocs()]) files[p] = body;
  for (const r of recipes) files[`recipes/${r.path}`] = recipeDoc(r);

  const index: Record<string, ReturnType<typeof indexEntry>> = {};
  for (const [p, body] of Object.entries(files)) index[p.replace(/\.md$/, '')] = indexEntry(p, body);

  files['routes.json'] = stableJson(buildRoutes(specs));
  for (const l of locales) files[`names/${l.code}.json`] = stableJson(buildNames(l.code, specs));
  files['index.json'] = stableJson(Object.fromEntries(Object.entries(index).sort(([a], [b]) => a.localeCompare(b))));
  files['README.md'] = [
    '# Medi knowledge (generated)',
    '',
    GENERATED_LINE,
    '',
    'Embedded into the API with `go:embed` (`internal/assistant/corpus.go`) and ranked with BM25',
    '(`internal/assistant/retrieve.go`). Regenerate from `media-manipulator-ui/` with `npm run export:medi`;',
    'the UI test `lib/assistant/knowledgeExport.test.ts` fails when this copy is stale.',
    '',
    '- `tools/<slug>.md`: one per primary tool page (aliases are keywords of their target)',
    '- `pages/<route>.md`: every other public route',
    '- `editors/{studio,vector,photo}/*.md`: what each editor can do, from its registries',
    '- `recipes/{photo,studio,vector,workflow}/*.md`: professional techniques with op examples (from `content/medi/recipes/`)',
    '- `routes.json`: the closed list of navigable targets',
    '- `names/<locale>.json`: localized tool/page names and locale-prefixed paths',
    '- `index.json`: doc id → title, kind, keywords, token estimate',
    '',
  ].join('\n');
  return Object.fromEntries(Object.entries(files).sort(([a], [b]) => a.localeCompare(b)));
}

/** The schema of routes.json, for the test (and documentation). */
export const routeEntrySchema = z.object({
  route: z.string().regex(/^\/[^\s]*$/),
  kind: z.enum(['page', 'tool', 'editor']),
  slug: z.string().optional(),
  presets: z.array(z.string()).optional(),
});

